<script setup lang="ts">
import UiIcon from '../components/UiIcon.vue'
import{computed,ref}from'vue';import{useApi,useAction,useEvents,download,stamp,contextUrl}from'../composables/api';import{route}from'../composables/state'
const api=useApi(),info=ref<any>({}),secrets=ref(false),file=ref<File>(),undo=ref(''),{busy,message,run}=useAction()
const infoText=computed(()=>'Последняя созданная копия: '+stamp(info.value.last_backup?.created)+(info.value.last_backup?' · '+Math.round(info.value.last_backup.size/1024)+' КБ':'')+'\nПоследнее восстановление: '+stamp(info.value.last_restore?.at))
async function load(){try{info.value=await api('/api/native/backups')}catch(e){message.value=(e as Error).message}}
function create(){void run(async()=>{const v=await api('/api/native/backups/create',{secrets:secrets.value});const r=await fetch(contextUrl(v.download),{cache:'no-store'});if(!r.ok)throw Error('Не удалось скачать копию');download(await r.blob(),v.name);message.value='Копия подготовлена и передана браузеру. Проверь папку загрузок на своём устройстве.';await load()})}
function restore(){void run(async()=>{if(!file.value)throw Error('Выбери архив .tar.gz');if(file.value.size>16*1048576)throw Error('Максимальный размер — 16 МБ');if(!confirm('Восстановить настройки панели из копии? Текущие настройки будут сохранены в копии для отмены. Пароль и системные файлы не меняются.')){message.value='';return}const v=await api('/api/native/backups/restore',file.value,{raw:true});message.value=v.message;undo.value=contextUrl(v.undo.download);await load()})}
void load();useEvents(()=>{if(route.active==='backups')void load()})
</script>
<template><header class="page-head"><h1><UiIcon name="archive"/>Резервные копии</h1></header>
<section class="card"><h2><UiIcon name="dl"/>Скачать копию на своё устройство</h2><p class="hint">Настройки панели и снимки конфигураций загрузки, автозапуска и ADB. Это не полный образ памяти. Пароль панели, сессии, runtime, музыка и приложения YAM не включаются.</p><pre class="out" id="backup-info">{{ infoText }}</pre>
<label class="toggle"><span>Включить секреты: токен Яндекса, агента и бинарную конфигурацию колонки. Архив не зашифрован — храни его приватно.</span><input type="checkbox" id="backup-secrets" v-model="secrets"></label><button class="btn primary" id="backup-create" @click="create" :disabled="busy"><UiIcon name="dl"/>Создать и скачать</button></section>
<section class="card"><h2><UiIcon name="undo"/>Восстановление настроек</h2><p class="hint">Восстанавливаются только настройки панели и включённые в копию токены. Снимки системных файлов предназначены для ручного восстановления; загрузка, root и прошивка автоматически не меняются. Перед восстановлением создаётся копия для отмены.</p><input class="field" id="backup-file" type="file" accept=".gz,.tgz" @change="file=($event.target as HTMLInputElement).files?.[0]"><button class="btn danger" id="backup-restore" @click="restore" :disabled="busy"><UiIcon name="undo"/>Восстановить настройки</button><a class="btn" id="backup-undo" :href="undo" :hidden="!undo">Скачать копию перед восстановлением</a><pre class="out" id="backup-status">{{ message }}</pre></section></template>